import type {
  FilterDataStructure,
  FilterForm,
  FilterValue,
} from 'models/Filters';
import {
  deriveTimePeriodSelection,
  getDefaultTimePeriodEnd,
  hasTimePeriodSelection,
  isTimePeriodSelectionAvailable,
  normalizeTimePeriodType,
  resolveTimePeriodSelection,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

import {
  areLegacyPeriodsEquivalent,
  isLegacyPeriodAvailable,
  resolveLegacyPeriod,
} from './legacyPeriodCompatibility';

export type TimePeriodCompatibilityPatch = {
  periods: FilterValue;
  period_type: FilterValue;
  dt_end: FilterValue;
};

export const TimePeriodResolutionOutcome = {
  PRESERVED: 'preserved',
  MAPPED: 'mapped',
  DEFAULTED: 'defaulted',
  INVALID: 'invalid',
} as const;

export type TimePeriodResolutionOutcome =
  (typeof TimePeriodResolutionOutcome)[keyof typeof TimePeriodResolutionOutcome];

export type PerformanceToolTimePeriodResolution = {
  patch: TimePeriodCompatibilityPatch;
  outcome: TimePeriodResolutionOutcome;
};

export const matchesTimePeriodPatch = (
  form: FilterForm,
  patch: TimePeriodCompatibilityPatch,
): boolean =>
  form.periods === patch.periods &&
  form.period_type === patch.period_type &&
  form.dt_end === patch.dt_end;

const LegacyTimePeriodType = {
  YTD: 'YTD',
  MTD: 'MTD',
  L3M: 'L3M',
  QTD: 'QTD',
  LQ: 'LQ',
} as const;

type LegacyTimePeriodType =
  (typeof LegacyTimePeriodType)[keyof typeof LegacyTimePeriodType];

const YtdMonthPeriodType = {
  YTD: 'YTD',
  MONTH: 'MONTH',
} as const;

type YtdMonthPeriodType =
  (typeof YtdMonthPeriodType)[keyof typeof YtdMonthPeriodType];

const LEGACY_TO_CANONICAL: Partial<
  Record<LegacyTimePeriodType, TimePeriodType>
> = {
  [LegacyTimePeriodType.YTD]: TimePeriodType.YTD,
  [LegacyTimePeriodType.MTD]: TimePeriodType.MTH,
  [LegacyTimePeriodType.L3M]: TimePeriodType.R3M,
  [LegacyTimePeriodType.QTD]: TimePeriodType.QTR,
  [LegacyTimePeriodType.LQ]: TimePeriodType.QTR,
};

const CANONICAL_TO_LEGACY: Partial<
  Record<TimePeriodType, LegacyTimePeriodType>
> = {
  [TimePeriodType.YTD]: LegacyTimePeriodType.YTD,
  [TimePeriodType.MTH]: LegacyTimePeriodType.MTD,
  [TimePeriodType.R3M]: LegacyTimePeriodType.L3M,
  [TimePeriodType.QTR]: LegacyTimePeriodType.QTD,
};

const YTD_MONTH_TO_LEGACY: Record<YtdMonthPeriodType, LegacyTimePeriodType> = {
  [YtdMonthPeriodType.YTD]: LegacyTimePeriodType.YTD,
  [YtdMonthPeriodType.MONTH]: LegacyTimePeriodType.MTD,
};

const CANONICAL_TO_YTD_MONTH: Partial<
  Record<TimePeriodType, YtdMonthPeriodType>
> = {
  [TimePeriodType.YTD]: YtdMonthPeriodType.YTD,
  [TimePeriodType.MTH]: YtdMonthPeriodType.MONTH,
};

const normalizeYtdMonthPeriodType = (
  value: FilterValue,
): YtdMonthPeriodType | null => {
  const normalized = String(value ?? '')
    .trim()
    .toUpperCase();

  return (
    Object.values(YtdMonthPeriodType).find(
      (periodType) => periodType === normalized,
    ) ?? null
  );
};

export const usesPerformanceToolTimePeriod = (
  filterData: FilterDataStructure,
): boolean => Boolean(filterData.time_period?.enabled);

const usesLegacyContract = (filterData: FilterDataStructure): boolean =>
  Boolean(filterData.periods?.enabled);

const usesYtdMonthContract = (filterData: FilterDataStructure): boolean => {
  const ytdMonth = filterData['ytd-month'];
  const availableValues =
    ytdMonth?.values
      ?.map((option) => option?.value)
      .filter((value) => value != null && value !== '') ?? [];

  return Boolean(
    ytdMonth?.enabled &&
    availableValues.length > 0 &&
    availableValues.every(
      (value) => normalizeYtdMonthPeriodType(value) !== null,
    ),
  );
};

export const supportsTimePeriodMigration = (
  filterData: FilterDataStructure,
): boolean =>
  usesPerformanceToolTimePeriod(filterData) ||
  usesLegacyContract(filterData) ||
  usesYtdMonthContract(filterData);

const hasCompleteCanonicalFields = (filters: FilterForm): boolean =>
  filters.period_type != null &&
  filters.period_type !== '' &&
  filters.dt_end != null &&
  filters.dt_end !== '';

const isLegacyTimePeriodType = (
  value: FilterValue,
): value is LegacyTimePeriodType =>
  Object.values(LegacyTimePeriodType).includes(value as LegacyTimePeriodType);

const findAvailableYtdMonthPeriod = (
  filterData: FilterDataStructure,
  value: FilterValue,
): FilterValue | undefined => {
  const normalizedValue = normalizeYtdMonthPeriodType(value);
  if (!normalizedValue) return undefined;

  return filterData['ytd-month']?.values?.find(
    (option) => normalizeYtdMonthPeriodType(option?.value) === normalizedValue,
  )?.value;
};

const resolveYtdMonthPeriod = (
  filterData: FilterDataStructure,
  candidate: FilterValue,
): FilterValue => {
  const availableCandidate = findAvailableYtdMonthPeriod(filterData, candidate);
  if (availableCandidate !== undefined) return availableCandidate;

  const defaultValue = filterData['ytd-month']?.default?.value ?? null;
  return findAvailableYtdMonthPeriod(filterData, defaultValue) ?? defaultValue;
};

const getLegacyCandidateFromYtdMonth = (value: FilterValue): FilterValue => {
  const normalizedValue = normalizeYtdMonthPeriodType(value);
  return normalizedValue ? YTD_MONTH_TO_LEGACY[normalizedValue] : null;
};

const getYtdMonthCandidateFromLegacy = (value: FilterValue): FilterValue => {
  if (!isLegacyTimePeriodType(value)) return null;

  const canonicalType = LEGACY_TO_CANONICAL[value];
  return canonicalType ? (CANONICAL_TO_YTD_MONTH[canonicalType] ?? null) : null;
};

const getYtdMonthCandidateFromCanonical = (value: FilterValue): FilterValue => {
  const canonicalType = normalizeTimePeriodType(value);
  return canonicalType ? (CANONICAL_TO_YTD_MONTH[canonicalType] ?? null) : null;
};

const isCanonicalPeriodTypeAvailable = (
  filterData: FilterDataStructure,
  periodType: TimePeriodType | '' | null | undefined,
): periodType is TimePeriodType => {
  if (!periodType) return false;

  return (
    filterData.time_period?.values?.some(
      ({ value }) => normalizeTimePeriodType(value) === periodType,
    ) ?? false
  );
};

const isQtdFallbackMapping = (
  filterData: FilterDataStructure,
  sourcePeriod: FilterValue,
  resolvedPeriod: FilterValue,
): boolean => {
  const supportsQtdFallback =
    sourcePeriod === LegacyTimePeriodType.MTD ||
    sourcePeriod === LegacyTimePeriodType.L3M;

  return (
    supportsQtdFallback &&
    areLegacyPeriodsEquivalent(resolvedPeriod, LegacyTimePeriodType.QTD) &&
    isLegacyPeriodAvailable(filterData, resolvedPeriod)
  );
};

const resolveLegacyOutcome = (
  resolvedPeriod: FilterValue,
  isMapped: boolean,
): TimePeriodResolutionOutcome => {
  if (isMapped) return TimePeriodResolutionOutcome.MAPPED;
  if (resolvedPeriod != null) return TimePeriodResolutionOutcome.DEFAULTED;
  return TimePeriodResolutionOutcome.INVALID;
};

const getLegacyCandidate = (periodType: FilterValue): FilterValue => {
  const normalizedType = normalizeTimePeriodType(periodType);
  if (!normalizedType) return null;

  return CANONICAL_TO_LEGACY[normalizedType] ?? null;
};

const getCanonicalDefaultSelection = (filterData: FilterDataStructure) => {
  const timePeriod = filterData.time_period;
  const defaultType = normalizeTimePeriodType(timePeriod?.default?.value);

  if (!isCanonicalPeriodTypeAvailable(filterData, defaultType)) return null;

  return resolveTimePeriodSelection(
    defaultType,
    timePeriod?.default_dt_end,
    timePeriod?.max_dt_end,
  );
};

const toCanonicalPatch = (
  selection: ReturnType<typeof resolveTimePeriodSelection>,
): TimePeriodCompatibilityPatch => ({
  periods: null,
  period_type: selection?.periodType ?? null,
  dt_end: selection?.dtEnd ?? null,
});

const toLegacyPatch = (periods: FilterValue): TimePeriodCompatibilityPatch => ({
  periods,
  period_type: null,
  dt_end: null,
});

const resolveCanonicalDefault = (
  filterData: FilterDataStructure,
): PerformanceToolTimePeriodResolution => {
  const selection = getCanonicalDefaultSelection(filterData);

  return {
    patch: toCanonicalPatch(selection),
    outcome: selection
      ? TimePeriodResolutionOutcome.DEFAULTED
      : TimePeriodResolutionOutcome.INVALID,
  };
};

const resolveCanonicalFields = (
  filterData: FilterDataStructure,
  legacyPeriod: FilterValue,
  sourceDtEnd?: FilterValue,
): PerformanceToolTimePeriodResolution => {
  const timePeriod = filterData.time_period;
  const maxDtEnd = timePeriod?.max_dt_end;
  const mappedType = isLegacyTimePeriodType(legacyPeriod)
    ? LEGACY_TO_CANONICAL[legacyPeriod]
    : undefined;

  if (maxDtEnd && isCanonicalPeriodTypeAvailable(filterData, mappedType)) {
    const selection =
      resolveTimePeriodSelection(mappedType, sourceDtEnd, maxDtEnd) ??
      deriveTimePeriodSelection(
        mappedType,
        getDefaultTimePeriodEnd(mappedType, maxDtEnd),
        maxDtEnd,
      );

    if (selection) {
      return {
        patch: toCanonicalPatch(selection),
        outcome: TimePeriodResolutionOutcome.MAPPED,
      };
    }
  }

  return resolveCanonicalDefault(filterData);
};

const resolveLegacyFields = (
  filterData: FilterDataStructure,
  periodType: FilterValue,
): PerformanceToolTimePeriodResolution => {
  const legacyCandidate = getLegacyCandidate(periodType);
  const mappedPeriod = resolveLegacyPeriod(filterData, legacyCandidate);
  const usesDirectMapping =
    areLegacyPeriodsEquivalent(legacyCandidate, mappedPeriod) &&
    isLegacyPeriodAvailable(filterData, mappedPeriod);
  const usesQtdMapping = isQtdFallbackMapping(
    filterData,
    legacyCandidate,
    mappedPeriod,
  );

  return {
    patch: toLegacyPatch(mappedPeriod),
    outcome: resolveLegacyOutcome(
      mappedPeriod,
      usesDirectMapping || usesQtdMapping,
    ),
  };
};

const resolveCanonicalSource = (
  previousForm: FilterForm,
  targetFilterData: FilterDataStructure,
): PerformanceToolTimePeriodResolution => {
  const timePeriod = targetFilterData.time_period;
  const normalizedType = normalizeTimePeriodType(previousForm.period_type);

  if (
    isCanonicalPeriodTypeAvailable(targetFilterData, normalizedType) &&
    isTimePeriodSelectionAvailable(
      normalizedType,
      previousForm.dt_end,
      timePeriod?.max_dt_end,
    )
  ) {
    const selection = resolveTimePeriodSelection(
      normalizedType,
      previousForm.dt_end,
      timePeriod?.max_dt_end,
    );
    return {
      patch: toCanonicalPatch(selection),
      outcome: TimePeriodResolutionOutcome.PRESERVED,
    };
  }

  return resolveCanonicalDefault(targetFilterData);
};

const resolveLegacySource = (
  previousForm: FilterForm,
  targetFilterData: FilterDataStructure,
): PerformanceToolTimePeriodResolution => {
  const previousPeriod = previousForm.periods;

  if (isLegacyPeriodAvailable(targetFilterData, previousPeriod)) {
    return {
      patch: toLegacyPatch(previousPeriod),
      outcome: TimePeriodResolutionOutcome.PRESERVED,
    };
  }

  const resolvedPeriod = resolveLegacyPeriod(targetFilterData, previousPeriod);
  const usesQtdMapping = isQtdFallbackMapping(
    targetFilterData,
    previousPeriod,
    resolvedPeriod,
  );
  const usesAliasMapping =
    areLegacyPeriodsEquivalent(previousPeriod, resolvedPeriod) &&
    isLegacyPeriodAvailable(targetFilterData, resolvedPeriod);

  return {
    patch: toLegacyPatch(resolvedPeriod),
    outcome: resolveLegacyOutcome(
      resolvedPeriod,
      usesAliasMapping || usesQtdMapping,
    ),
  };
};

export const resolvePerformanceToolKpiTimePeriodChange = (
  previousForm: FilterForm,
  targetFilterData: FilterDataStructure,
): PerformanceToolTimePeriodResolution => {
  const sourceUsesCanonicalContract = hasTimePeriodSelection(
    previousForm.period_type,
    previousForm.dt_end,
  );

  if (usesPerformanceToolTimePeriod(targetFilterData)) {
    if (sourceUsesCanonicalContract) {
      return resolveCanonicalSource(previousForm, targetFilterData);
    }

    return resolveCanonicalFields(
      targetFilterData,
      previousForm.periods,
      previousForm.dt_end,
    );
  }

  if (sourceUsesCanonicalContract) {
    return resolveLegacyFields(targetFilterData, previousForm.period_type);
  }

  return resolveLegacySource(previousForm, targetFilterData);
};

export const recalculatePerformanceToolTimePeriod = (
  previousForm: FilterForm,
  targetFilterData: FilterDataStructure,
): TimePeriodCompatibilityPatch => {
  if (!usesPerformanceToolTimePeriod(targetFilterData)) {
    return resolveLegacySource(previousForm, targetFilterData).patch;
  }

  const timePeriod = targetFilterData.time_period;
  const normalizedType = normalizeTimePeriodType(previousForm.period_type);
  let recalculatedSelection: ReturnType<typeof deriveTimePeriodSelection> =
    null;

  if (
    timePeriod?.max_dt_end &&
    isCanonicalPeriodTypeAvailable(targetFilterData, normalizedType)
  ) {
    recalculatedSelection =
      resolveTimePeriodSelection(
        normalizedType,
        previousForm.dt_end,
        timePeriod.max_dt_end,
      ) ??
      deriveTimePeriodSelection(
        normalizedType,
        getDefaultTimePeriodEnd(normalizedType, timePeriod.max_dt_end),
        timePeriod.max_dt_end,
      );
  }

  return toCanonicalPatch(
    recalculatedSelection ?? getCanonicalDefaultSelection(targetFilterData),
  );
};

export const resolvePerformanceToolTimePeriodTransition = (
  previousForm: FilterForm,
  targetFilterData: FilterDataStructure,
): TimePeriodCompatibilityPatch | null => {
  const sourceUsesCanonicalContract = hasTimePeriodSelection(
    previousForm.period_type,
    previousForm.dt_end,
  );

  if (usesPerformanceToolTimePeriod(targetFilterData)) {
    if (sourceUsesCanonicalContract) return null;

    return resolveCanonicalFields(
      targetFilterData,
      previousForm.periods,
      previousForm.dt_end,
    ).patch;
  }

  if (!sourceUsesCanonicalContract) return null;

  return resolveLegacyFields(targetFilterData, previousForm.period_type).patch;
};

const clearCanonicalContract = (filters: FilterForm): void => {
  delete filters.period_type;
  delete filters.dt_end;
};

const migrateToCanonicalContract = (
  sourceFilters: FilterForm,
  targetFilterData: FilterDataStructure,
): FilterForm => {
  const migrated = { ...sourceFilters };

  if (hasCompleteCanonicalFields(migrated)) {
    delete migrated.periods;
    delete migrated['ytd-month'];
    return migrated;
  }

  const sourcePeriod =
    migrated.periods ?? getLegacyCandidateFromYtdMonth(migrated['ytd-month']);
  if (sourcePeriod == null || sourcePeriod === '') return migrated;

  const canonicalFields = resolveCanonicalFields(
    targetFilterData,
    sourcePeriod,
    migrated.dt_end,
  ).patch;
  delete migrated.periods;
  delete migrated['ytd-month'];
  migrated.period_type = canonicalFields.period_type;
  migrated.dt_end = canonicalFields.dt_end;
  return migrated;
};

const migrateToLegacyContract = (
  sourceFilters: FilterForm,
  targetFilterData: FilterDataStructure,
): FilterForm => {
  const migrated = { ...sourceFilters };

  if (migrated.periods != null) {
    const targetPeriod = resolveLegacyPeriod(
      targetFilterData,
      migrated.periods,
      migrated.periods,
    );

    if (areLegacyPeriodsEquivalent(migrated.periods, targetPeriod)) {
      migrated.periods = targetPeriod;
    }

    clearCanonicalContract(migrated);
    delete migrated['ytd-month'];
    return migrated;
  }

  const sourceUsesCanonicalContract = migrated.period_type != null;
  const sourceUsesYtdMonthContract = migrated['ytd-month'] != null;
  if (!sourceUsesCanonicalContract && !sourceUsesYtdMonthContract) {
    return migrated;
  }

  const legacyCandidate = sourceUsesCanonicalContract
    ? getLegacyCandidate(migrated.period_type)
    : getLegacyCandidateFromYtdMonth(migrated['ytd-month']);

  migrated.periods = resolveLegacyPeriod(targetFilterData, legacyCandidate);
  clearCanonicalContract(migrated);
  delete migrated['ytd-month'];

  return migrated;
};

const resolveTimeFrameYear = (dtEnd: FilterValue): number | null => {
  if (typeof dtEnd !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dtEnd)) {
    return null;
  }

  return Number(dtEnd.slice(0, 4));
};

const migrateToYtdMonthContract = (
  sourceFilters: FilterForm,
  targetFilterData: FilterDataStructure,
): FilterForm => {
  const migrated = { ...sourceFilters };
  const nativeYtdMonth = migrated['ytd-month'];

  if (nativeYtdMonth != null) {
    const availableNativeValue = findAvailableYtdMonthPeriod(
      targetFilterData,
      nativeYtdMonth,
    );
    if (availableNativeValue !== undefined) {
      migrated['ytd-month'] = availableNativeValue;
    }
    delete migrated.periods;
    clearCanonicalContract(migrated);
    return migrated;
  }

  const sourceUsesCanonicalContract = migrated.period_type != null;
  const sourceUsesLegacyContract = migrated.periods != null;
  if (!sourceUsesCanonicalContract && !sourceUsesLegacyContract) {
    return migrated;
  }

  const ytdMonthCandidate = sourceUsesCanonicalContract
    ? getYtdMonthCandidateFromCanonical(migrated.period_type)
    : getYtdMonthCandidateFromLegacy(migrated.periods);
  migrated['ytd-month'] = resolveYtdMonthPeriod(
    targetFilterData,
    ytdMonthCandidate,
  );

  if (sourceUsesCanonicalContract && targetFilterData.time_frame?.enabled) {
    const timeFrameYear = resolveTimeFrameYear(migrated.dt_end);
    if (timeFrameYear !== null) migrated.time_frame = timeFrameYear;
  }

  delete migrated.periods;
  clearCanonicalContract(migrated);
  return migrated;
};

export const migrateTimePeriodFilters = (
  sourceFilters: FilterForm,
  targetFilterData: FilterDataStructure,
): FilterForm => {
  if (usesPerformanceToolTimePeriod(targetFilterData)) {
    return migrateToCanonicalContract(sourceFilters, targetFilterData);
  }

  if (usesLegacyContract(targetFilterData)) {
    return migrateToLegacyContract(sourceFilters, targetFilterData);
  }

  if (usesYtdMonthContract(targetFilterData)) {
    return migrateToYtdMonthContract(sourceFilters, targetFilterData);
  }

  return { ...sourceFilters };
};
